import { parseArgs } from 'node:util';
import path from 'node:path';
import { readdir } from 'node:fs/promises';
import { pathToFileURL } from 'node:url';

type CommandModule = {
  meta: { name: string; description?: string };
  config?: { args?: readonly string[]; options?: Record<string, any> };
  handler: (argv: string[]) => Promise<void> | void;
};

const commandsRoot = path.join(path.dirname(new URL(import.meta.url).pathname), 'commands');

async function collectCommands() {
  let groups;
  try {
    groups = await readdir(commandsRoot, { withFileTypes: true });
  } catch (err) {
    // when running as a bundled single-file binary the src/commands folder
    // might not be discoverable via the file system — fall back to a static
    // import registry so bundlers can include modules.
    const registry: Record<string, Record<string, CommandModule>> = {};
    // statically import known commands so bundle contains them. Expand this list as you add commands.
    const cleanupStale = (await import('./commands/cleanup/stale')) as CommandModule;
    const cleanupOrphaned = (await import('./commands/cleanup/orphaned')) as CommandModule;
    const inspectStats = (await import('./commands/inspect/stats')) as CommandModule;
    const jobsList = (await import('./commands/jobs/list')) as CommandModule;

    registry.cleanup = {
      stale: cleanupStale,
      orphaned: cleanupOrphaned,
    };
    registry.inspect = { stats: inspectStats };
    registry.jobs = { list: jobsList };

    return registry;
  }
  const registry: Record<string, Record<string, CommandModule>> = {};

  for (const g of groups) {
    if (!g.isDirectory()) continue;
    const groupName = g.name;
    registry[groupName] = {};
    const groupPath = path.join(commandsRoot, groupName);
    const files = await readdir(groupPath, { withFileTypes: true });
    for (const f of files) {
      if (!f.isFile()) continue;
      const name = f.name.replace(/\.tsx?$|\.js$/i, '');
      const filePath = path.join(groupPath, f.name);
      const moduleUrl = pathToFileURL(filePath).href;
      const mod = (await import(moduleUrl)) as CommandModule;
      registry[groupName][name] = mod;
    }
  }

  return registry;
}

function help(registry: Record<string, Record<string, CommandModule>>) {
  console.log('meilisearch-cli — available commands:\n');
  for (const grp of Object.keys(registry)) {
    console.log(grp + ':');
    const groupCommands = registry[grp] ?? {};
    for (const [cmd, mod] of Object.entries(groupCommands)) {
      const meta = mod?.meta;
      console.log(`  ${grp} ${cmd}\t ${meta?.description ?? ''}`);
    }
    console.log('');
  }
  console.log('Examples:');
  console.log('  meilisearch-cli cleanup stale --dry-run');
  console.log('  meilisearch-cli inspect stats --verbose');
}

async function run() {
  const argv = process.argv.slice(2);
  const registry = await collectCommands();

  if (argv.length === 0) {
    help(registry);
    return;
  }

  const [group, command, ...rest] = argv;
  if (!group || !command) {
    console.error('Expected <group> <command> — run with no args for help');
    process.exit(2);
  }

  const groupMap = registry[group];
  if (!groupMap) {
    console.error('Unknown command group', group);
    help(registry);
    process.exit(2);
  }

  const cmd = groupMap[command];
  if (!cmd) {
    console.error('Unknown command', `${group} ${command}`);
    help(registry);
    process.exit(2);
  }

  // parse args for the specific subcommand if it declares config
  if (cmd.config) {
    const parsed = parseArgs({ args: rest, options: cmd.config.options ?? {}, allowPositionals: true } as const);
    // freeze parsed values for runtime immutability
    deepFreeze(parsed);
    // let handler decide what to do/use; pass argv if it needs raw values
    await cmd.handler(rest);
    return;
  }

  await cmd.handler(rest);
}

function deepFreeze<T>(obj: T): Readonly<T> {
  if (obj && typeof obj === 'object') {
    Object.getOwnPropertyNames(obj).forEach((name) => {
      // @ts-ignore access dynamic keys
      const value = obj[name];
      if (value && typeof value === 'object') deepFreeze(value);
    });
    return Object.freeze(obj) as Readonly<T>;
  }
  return obj;
}

run().catch((err) => {
  console.error('Unexpected error:', err);
  process.exit(1);
});


