import { parseArgs, type ParseArgsConfig } from 'node:util';

export const meta = { name: 'list', description: 'List jobs' };

export const config = {
  options: {
    verbose: { type: 'boolean', default: false }
  }
} as const satisfies ParseArgsConfig;

export async function handler(argv: string[]) {
  const { values } = parseArgs({ args: argv, options: config.options } as const);
  console.log('[jobs list] verbose:', values.verbose);
  console.log('Jobs: [ { id: "a1", status: "done" }, { id: "b2", status: "running" } ]');
}
