import { parseArgs, type ParseArgsConfig } from 'node:util';

export const meta = {
  name: 'orphaned',
  description: 'Cleanup orphaned resources',
};

export const config = {
  options: {
    'dry-run': { type: 'boolean', default: false },
  },
} as const satisfies ParseArgsConfig;

export async function handler(argv: string[]) {
  const { values } = parseArgs({ args: argv, options: config.options } as const);
  console.log('[cleanup orphaned] dryRun:', values['dry-run']);
  if (values['dry-run']) console.log('Everything would be cleaned up (dry-run).');
  else console.log('Cleaning up orphaned resources (real run).');
}
